const tr=k=>I18N[lang]?.[k]||I18N.zh[k]||k;
const money=n=>n==null?'待报价':new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(n);
const pickName=m=>m?.names?.[C.languages.indexOf(lang)]||m?.name||'';
const workerName=id=>state.project.workers.find(w=>w.id===id)?.name||'待分配';
const pill=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const statusPill=t=>pill(tr(t.status),({done:'good',blocked:'danger',review:'info',draft:'',assigned:'warning'})[t.status]||'info');
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
const empty=(title,sub='')=>`<div class="empty"><div class="symbol">◇</div><h3>${esc(title)}</h3><p>${esc(sub)}</p></div>`;
const metric=(value,label,sub='')=>`<div class="metric"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><small>${esc(sub)}</small></div>`;
const field=(label,name,value='',type='text',attrs='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,items,value='')=>`<label class="field">${esc(label)}<select name="${name}">${items.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const area=(label,name,value='',required=false)=>`<label class="field">${esc(label)}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const safePhoto=s=>typeof s==='string'&&(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s)||/^\/api\/assets\/[a-zA-Z0-9_-]+$/.test(s))?s:'';
const photoHTML=photos=>(photos||[]).length?`<div class="photos">${photos.map(p=>`<a class="photo-link" href="${safePhoto(p.data||p)}" target="_blank" rel="noopener"><img src="${safePhoto(p.data||p)}" alt="${esc(tr('photos'))}" loading="lazy"></a>`).join('')}</div>`:'';
function toast(s){let e=document.getElementById('toast');e.textContent=s;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',4200);}
function setSave(text,error=false){const e=document.getElementById('saveStatus');e.textContent=text;e.classList.toggle('error',error);}
function selectActive(){state=workspace.projects.find(p=>p.id===workspace.activeProjectId)||workspace.projects[0];workspace.activeProjectId=state.id;}
function invalidate(){state.approved=false;state.approvedAt=null;state.estimatesChanged=state.tasks.length>0;}
function save(){
 unsaved=true;setSave('正在保存…');
 const job=saving.catch(()=>{}).then(async()=>{C.validate(workspace);workspace._sync={serverRevision:cloudRevision,pending:serverRole==='owner',mutationId:C.uid('mutation')};let rev=await S.save(workspace,localRevision);localRevision=rev;workspace.revision=rev;unsaved=false;setSave(serverRole==='owner'?'已保存到此设备 · 正在同步':'已保存到此设备');channel?.postMessage({revision:rev});if(serverRole==='owner'&&!cloudConflict){clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,500);}return rev;}).catch(e=>{unsaved=true;setSave('保存失败 · '+e.message,true);document.getElementById('banner').innerHTML=`<div class="save-warning">${esc(e.message)} ${button('立即导出当前备份','export')} ${button('载入最新已保存数据','reloadLocal')}</div>`;throw e;});
 saving=job;job.catch(()=>{});return job;
}
function restoreObject(target,source){for(let k of Object.keys(target))if(!(k in source))delete target[k];for(let [k,v]of Object.entries(source)){if(v&&typeof v==='object'&&target[k]&&typeof target[k]==='object'&&Array.isArray(v)===Array.isArray(target[k])){if(Array.isArray(v))target[k].length=v.length;restoreObject(target[k],v);}else target[k]=C.clone(v);}return target;}
async function change(fn,text){let original=workspace,before=C.clone(workspace),saveStarted=false;try{fn();C.validate(workspace);if(serverRole==='foreman'){await api('/api/foreman',{method:'POST',body:JSON.stringify({expectedRevision:cloudRevision,operationId:C.uid('foremanop'),projects:workspace.projects})});await fetchCloud(false);}else{saveStarted=true;await save();}if(text)toast(text);screen();return true;}catch(e){if(!saveStarted){workspace=restoreObject(original,before);selectActive();}throw e;}}
async function api(path,options={}){let r=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(18000)});let d=await r.json();if(!r.ok){let e=Error(d.error||'请求失败');e.status=r.status;throw e;}return d;}
async function syncNow(){
 if(syncBusy||serverRole!=='owner'||cloudConflict)return;syncBusy=true;
 try{await saving;if(!workspace._sync?.pending)return;let snapshot=C.clone(workspace),localBefore=localRevision;delete snapshot.revision;delete snapshot._sync;
  const sentMutation=workspace._sync.mutationId;let d=await api('/api/workspace',{method:'PUT',body:JSON.stringify({expectedRevision:cloudRevision,mutationId:sentMutation,workspace:snapshot})});cloudRevision=d.revision;cloudOnline=true;
  saving=saving.catch(()=>{}).then(async()=>{workspace._sync={...workspace._sync,serverRevision:cloudRevision,pending:workspace._sync.mutationId!==sentMutation};localRevision=await S.save(workspace,localRevision);workspace.revision=localRevision;channel?.postMessage({revision:localRevision});});await saving;
  if(!workspace._sync.pending)setSave('已同步 · '+new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}));else{clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,300);}
 }catch(e){cloudOnline=false;if(e.status===409){cloudConflict=true;document.getElementById('banner').innerHTML=`<div class="save-warning">另一设备已更新项目。此设备的修改已保留，请导出备份后载入云端版本，再核对合并。 ${button('导出当前备份','export')} ${button('载入云端最新版本','reloadCloud')}</div>`;setSave('同步冲突 · 本机修改已保留',true);}else setSave('已保存到此设备 · 网络恢复后重试同步');}
 finally{syncBusy=false;}
}
let channel=null;try{channel=new BroadcastChannel('yuan-build-os');channel.onmessage=e=>{if(e.data.revision>localRevision)document.getElementById('banner').innerHTML=`<div class="notice warning">另一页面已保存新数据。为避免覆盖，请先载入最新记录。 ${button('载入最新记录','reloadLocal')}</div>`;};}catch{}
function renderNav(){let items=ownerRole?[['dashboard','◫'],['plan','▤'],['materials','▦'],['workers','◉'],['client','◈'],['drawing','⌗'],['designer','↧'],['settings','⚙']]:serverRole==='foreman'?[['dashboard','◫'],['plan','▤'],['materials','▦'],['workers','◉']]:[[serverRole==='customer'?'client':'workers','◇']];document.getElementById('nav').innerHTML=items.map(([id,icon])=>`<button class="${view===id?'active':''}" data-view="${id}">${icon}　${esc(tr(id))}</button>`).join('');}
function screen(){
 if(!state)return;document.documentElement.lang=lang;document.getElementById('lang').value=lang;document.getElementById('pageTitle').textContent=tr(view);document.getElementById('projectSubtitle').textContent=state.project.name;document.getElementById('projectSelect').innerHTML=workspace.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===state.id?'selected':''}>${esc(p.project.name)}</option>`).join('');
 const root=document.getElementById('root');
 if(view==='drawing'||view==='designer'){const existingBanner=document.getElementById('banner').innerHTML;tab=view==='drawing'?1:2;legacyScreen();document.getElementById('banner').innerHTML=existingBanner;}
 else root.innerHTML=({dashboard:dashboardHTML,plan:planHTML,materials:materialsHTML,workers:workerHTML,client:clientHTML,settings:settingsHTML}[view]||dashboardHTML)();
 renderNav();wireNew();
}
function dashboardHTML(){let p=state,today=C.today(),tasks=p.tasks.filter(t=>t.date<=today&&(t.endDate||t.date)>=today&&t.status!=='cancelled'),alerts=C.alerts(workspace),open=p.requests.filter(r=>r.status==='pending'),f=C.forecast(p,48),verified=p.tasks.filter(t=>t.status==='done').length;
 return `<section class="hero"><div class="eyebrow" style="color:#9ed6c1">YOUR SITE, IN ORDER</div><div class="row between"><div><h2>让今天的施工，有明确的下一步。</h2><p>${esc(p.project.name)} · 任务交到人，材料提前备，进度有记录。</p></div>${button('查看 7 日计划 →','go','plan','primary')}</div><div class="row" style="margin-top:12px">${pill('采购负责人 · Qi Yuan')}${pill('v3.4 · 施工管理')}${!p.approved?pill('图纸待复核','warning'):pill('图纸已审核','good')}</div></section>
 <div class="metrics">${metric(tasks.filter(t=>t.status!=='done').length,'今日待完成','已验收 '+tasks.filter(t=>t.status==='done').length+' 项')}${metric(open.length,'等待你审批','材料采购集中处理')}${metric(f.filter(x=>!x.known||x.shortage>0).length,'48 小时材料关注','含待盘点与数量缺口')}${metric(C.progress(p)+'%','任务执行进度',verified+' / '+p.tasks.filter(t=>t.status!=='cancelled').length+' 项已验收')}</div>
 <div class="grid two"><section><div class="row between"><h2>今天做什么</h2>${button('新建任务','newTask','','quiet')}</div><p class="muted">${today} · 发布 → 接单 → 施工 → 报告 → 验收</p>${tasks.length?tasks.slice(0,6).map(t=>taskCard(t)).join(''):empty('今天还没有施工任务','可以先生成计划草稿，再核对日期和负责人。')}${!p.tasks.length?button('生成施工计划草稿','generate','','primary'):''}</section>
 <section><div class="row between"><h2>需要你处理</h2>${pill(alerts.length+' 项')}</div>${alerts.length?alerts.slice(0,8).map(a=>`<div class="alert-item"><span class="dot ${a.level}"></span><div><div>${esc(a.text)}</div><span class="muted">${esc(workspace.projects.find(x=>x.id===a.projectId)?.project.name||'')}</span></div></div>`).join(''):empty('暂时没有异常','有任务、材料申请和到货记录后，系统会持续检查。')}</section></div>
 <section><div class="row between"><div><h2>未来 48 小时 · 材料准备</h2><p class="muted">按任务开始时间计算，并扣除已领用数量；待盘点库存不会被当成 0。</p></div>${button('打开材料台账 →','go','materials')}</div>${forecastTable(48,true)}</section>`;
}
function taskCard(t,worker=false){let req=C.taskMaterials(state,t),mats=C.catalog(state),blocked=C.blockers(state,t);return `<article class="task-card ${t.status}"><div class="row between">${statusPill(t)}<span class="muted">${esc(t.time)}–${esc(t.endTime)}</span></div><h3>${esc(C.title(t,lang))}</h3><div class="task-meta"><span>${esc(t.date)}</span><span>${esc(workerName(t.workerId))}</span>${t.estimated?`<span>${esc(({zh:'量 / 工期待核实',es:'Cantidad y plazo por confirmar',en:'Quantity and duration to confirm',hi:'मात्रा और समय की पुष्टि बाकी'})[lang])}</span>`:''}</div>${worker?`<p class="note-text">${esc(t.details||tr('noNotes'))}</p>${blocked.length?`<div class="notice warning">${esc(tr('dependencies'))}: ${blocked.map(x=>esc(C.title(x,lang))).join(' · ')}</div>`:''}<div class="subtle"><strong>${esc(tr('need'))}</strong>${req.length?req.map(m=>{let s=C.stock(state,m.materialId),mat=mats.find(x=>x.id===m.materialId);return `<p>${esc(pickName(mat))} · ${fmt(m.qty)} ${esc(mat?.unit||'')}<br><span class="muted">${esc(tr('remain'))} ${fmt(m.remaining)} · ${esc(tr('stock'))} ${s.known?fmt(s.qty):esc(tr('unknown'))}</span></p>`;}).join(''):`<p class="muted">${esc(tr('noMaterials'))}</p>`}</div>`:''}<div class="progress"><span style="width:${Number(t.progress)||0}%"></span></div>${t.status==='blocked'?`<p class="notice danger note-text">${esc(t.blockReason||'')}</p>`:''}<div class="actions">${worker?workerActions(t):button('详情与编辑','editTask',t.id)+(t.status==='draft'?button('发布任务','publishTask',t.id,'primary'):'')+(ownerRole&&t.status==='review'?button('验收','reviewTask',t.id,'primary'):'')}</div></article>`;}
function workerActions(t){if(serverRole==='foreman')return '<p class="muted">工人通过自己的账户接单和提交进度。</p>';let a='';if(t.status==='assigned')a+=button(tr('ack'),'ackTask',t.id,'primary');if(['accepted','blocked'].includes(t.status))a+=button(tr('start'),'startTask',t.id,'primary');if(['in_progress','blocked'].includes(t.status))a+=button(tr('report'),'reportTask',t.id,'primary');if(['accepted','in_progress'].includes(t.status))a+=button(tr('block'),'blockTask',t.id);if(!['done','cancelled','review'].includes(t.status))a+=button(tr('request'),'taskRequest',t.id);if(t.status==='review')a+=`<p class="muted">${esc(tr('pendingReview'))}</p>`;return a;}
function planHTML(){let list=state.tasks.filter(t=>t.status!=='cancelled'&&(!taskFilter||t.workerId===taskFilter)),dates=Array.from({length:7},(_,i)=>C.day(boardDate,i));return `<section><div class="row between"><div><h2>7 日计划与每日分工</h2><p class="muted">工长明确工作要求、完成标准、负责人和材料；只有发布后的任务才进入工人工作台。</p></div><div class="row">${button('生成计划草稿','generate')}${button('新建任务','newTask','','primary')}${button('发布本周草稿','publishWeek')}</div></div><div class="row" style="margin-top:15px"><input id="boardDate" type="date" value="${boardDate}" aria-label="计划起始日期">${button('今天','todayBoard')}<select id="taskFilter" aria-label="按员工筛选"><option value="">全部员工</option>${state.project.workers.map(w=>`<option value="${esc(w.id)}" ${taskFilter===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select><div class="tabs">${button('7 日看板','planMode','week',planMode==='week'?'active':'')}${button('全部任务','planMode','list',planMode==='list'?'active':'')}</div></div>${!state.project.workers.length?`<div class="notice warning">先添加施工人员，再发布任务。 ${ownerRole?button('添加员工','newWorker'):''}</div>`:''}${state.legacyDraftPlan.length?`<p class="muted">已保留旧文件的 ${state.legacyDraftPlan.length} 条草稿工序；不会自动当成已发布任务。</p>`:''}</section>
 ${!list.length?`<section>${empty('开始安排这次施工','库存尚未盘点，也可以先制定计划。')}${button('生成工作日计划草稿','generate','','primary')}</section>`:planMode==='week'?`<div class="day-grid">${dates.map(d=>`<div class="day-column"><div class="day-heading ${d===C.today()?'today':''}">${d} · ${new Intl.DateTimeFormat('zh',{weekday:'short',timeZone:'UTC'}).format(new Date(d+'T12:00Z'))}</div>${list.filter(t=>t.date<=d&&(t.endDate||t.date)>=d).map(t=>taskCard(t)).join('')||'<p class="muted">暂无安排</p>'}${button('＋ 添加','newTaskDate',d,'quiet')}</div>`).join('')}</div>`:`<section><div class="scroll"><table><thead><tr><th>任务</th><th>日期与时段</th><th>负责人</th><th>状态</th><th>进度</th><th></th></tr></thead><tbody>${[...list].sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)).map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.date)}${t.endDate!==t.date?' → '+esc(t.endDate):''}<br>${t.time}–${t.endTime}</td><td>${esc(workerName(t.workerId))}</td><td>${statusPill(t)}</td><td>${t.progress||0}%</td><td>${button('编辑','editTask',t.id)}</td></tr>`).join('')}</tbody></table></div></section>`}`;}
function forecastTable(hours,compact=false){let rows=C.forecast(state,hours);return rows.length?`<div class="scroll"><table><thead><tr><th>材料 / 单位</th><th>任务剩余需求</th><th>现货</th><th>在途</th><th>缺口</th>${compact?'':'<th>待审批 / 待下单</th><th>建议申请</th><th>最晚下单日</th>'}<th>最早使用</th></tr></thead><tbody>${rows.map(m=>`<tr><td><b>${esc(pickName(m))}</b><br><span class="muted">${esc(m.unit)}</span></td><td>${fmt(m.demand)}</td><td>${m.known?fmt(m.onHand):pill('待盘点','warning')}</td><td>${fmt(m.ordered)}</td><td>${m.shortage==null?'—':m.shortage>0?pill(fmt(m.shortage),'danger'):pill('齐备','good')}</td>${compact?'':`<td>${fmt(m.pending)}</td><td>${m.suggested==null?'先盘点':fmt(m.suggested)}<br><span class="muted">包装 ${fmt(m.pack)}</span></td><td>${m.latestOrder||'—'}</td>`}<td>${new Intl.DateTimeFormat('sv',{timeZone:'Europe/Madrid',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(m.firstDue)}</td></tr>`).join('')}</tbody></table></div>`:empty('这个时间范围尚无已申报的材料需求','给每日任务填写用料，预测会自动更新。');}
function materialsHTML(){return `<section><div class="row between"><div><h2>提前备料，集中采购</h2><p class="muted">采购、付款和运输负责人：Qi Yuan。申请、审批、下单和实际到货分别登记。</p></div><div class="row">${ownerRole?button('新增材料','newMaterial'):''}${button('新增采购申请','newRequest','','primary')}${ownerRole?button('导出采购 CSV','csv'):''}</div></div><div class="tabs">${[['48','48 小时预测'],['168','7 日预测'],['requests','采购审批与到货'],['stock','库存与领用']].map(([id,l])=>button(l,'materialView',id,materialView===id?'active':'')).join('')}</div>${['48','168'].includes(materialView)?`<div class="notice warning">预测包含草稿任务和逾期未完成任务，便于提前备料。在途只在预计到货不晚于使用时间时抵扣；未下单申请单独显示。所有模板材料量均为粗估，须现场核定。</div>${forecastTable(+materialView)}<div class="row" style="margin-top:15px">${button('按缺口生成申请','forecastRequest',materialView,'primary')}${button('先盘点已有材料','materialView','stock')}</div>`:materialView==='stock'?inventoryHTML():requestsHTML()}</section>`;}
function requestsHTML(){let list=[...state.requests].reverse();return list.length?`<div class="scroll"><table><thead><tr><th>申请 / 需要时间</th><th>材料</th><th>申请原因</th><th>金额（未含税调整）</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.map(r=>{let priced=r.lines.every(l=>l.price!=null),cost=r.lines.reduce((n,l)=>n+l.qty*(l.price||0),0);return `<tr><td><b>${esc(r.code)}</b><br>${esc(r.needDate)}${r.urgent?'<br>'+pill('临时追加','danger'):''}<br><span class="muted">${esc(r.requestedBy||'Qi Yuan')}</span></td><td>${r.lines.map(l=>{let m=C.catalog(state).find(x=>x.id===l.materialId);return `${esc(pickName(m))} · ${fmt(l.qty)} ${esc(m?.unit||'')}<br><span class="muted">已到 ${fmt(l.received||0)}</span>`;}).join('<br>')}</td><td class="note-text">${esc(r.reason)}<br><span class="muted">${esc(r.supplier||'')}<br>${r.eta?'预计 '+esc(r.eta):''}</span></td><td>${ownerRole?(priced?money(cost):'待报价'):'负责人管理'}</td><td>${pill(({pending:'待审批',approved:'已批准 · 待下单',ordered:'已下单',partial:'部分到货',received:'已收齐',rejected:'已拒绝',cancelled:'已取消'})[r.status]||r.status,r.status==='pending'?'warning':r.status==='received'?'good':'info')}</td><td><div class="stack">${ownerRole&&r.status==='pending'?button('审批','approveRequest',r.id,'primary')+button('拒绝','rejectRequest',r.id):''}${ownerRole&&r.status==='approved'?button('登记下单','orderRequest',r.id,'primary')+button('取消','cancelRequest',r.id):''}${ownerRole&&['ordered','partial'].includes(r.status)?button('实际到货入库','receiveRequest',r.id,'primary'):''}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('还没有采购申请','可手动申报，也可按材料缺口汇总申请。');}
function inventoryHTML(){let cat=C.catalog(state),hist=[...state.movements].reverse().slice(0,60);return `<p class="muted">首次按现场实际数量盘点。领用会扣减现货，退回增加库存；任务净领用量会抵扣未来需求。</p><div class="scroll"><table><thead><tr><th>材料</th><th>单位</th><th>现货</th><th>包装 / 交期</th><th>操作</th></tr></thead><tbody>${cat.map(m=>{let s=C.stock(state,m.id);return `<tr><td>${esc(pickName(m))}</td><td>${esc(m.unit)}</td><td>${s.known?'<b>'+fmt(s.qty)+'</b>':pill('待盘点','warning')}</td><td>${fmt(m.pack)} / ${m.lead} 天</td><td>${button('盘点','countStock',m.id)} ${button('领用 / 退回','moveStock',m.id)} ${ownerRole?button('规格','editMaterial',m.id):''}</td></tr>`;}).join('')}</tbody></table></div><h3 style="margin-top:25px">最近库存流水</h3>${hist.length?`<div class="scroll"><table><thead><tr><th>时间</th><th>材料</th><th>操作</th><th>变动</th><th>任务 / 备注</th></tr></thead><tbody>${hist.map(m=>`<tr><td>${new Date(m.at).toLocaleString('es-ES')}</td><td>${esc(pickName(cat.find(x=>x.id===m.materialId)))}</td><td>${({count:'实盘调整',receipt:'实际到货',issue:'领用',return:'退回',waste:'损耗'})[m.type]}</td><td>${m.delta>0?'+':''}${fmt(m.delta)}</td><td>${esc(state.tasks.find(t=>t.id===m.taskId)?.title||'')}<br>${esc(m.note||'')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">暂无库存流水。</p>'}`;}
function workerHTML(){const workers=state.project.workers.filter(w=>w.active!==false);if(!workerFilter||!workers.some(w=>w.id===workerFilter))workerFilter=workers[0]?.id||'';const tasks=state.tasks.filter(t=>t.workerId===workerFilter&&!['draft','cancelled'].includes(t.status));let today=C.today();return `<section><div class="row between"><div><h2>${esc(tr('workRequirements'))}</h2><p class="muted">${esc(tr('materialsPending'))}</p></div>${ownerRole?button('添加员工','newWorker'):''}</div>${ownerRole?`<p class="notice warning">${esc(tr('localView'))}</p>`:''}<div class="row"><select id="workerFilter" aria-label="${esc(tr('worker'))}">${workers.map(w=>`<option value="${esc(w.id)}" ${w.id===workerFilter?'selected':''}>${esc(w.name)}</option>`).join('')}</select>${ownerRole?button('管理员工','manageWorkers'):''}<span class="badge">${esc(tr('date'))} · ${today}</span></div></section>${!workers.length?`<section>${empty(tr('noWorkers'))}</section>`:`<div class="grid two"><section><h2>${esc(tr('today'))}</h2>${tasks.filter(t=>t.date<=today&&(t.endDate||t.date)>=today).map(t=>taskCard(t,true)).join('')||empty(tr('empty'),tr('emptySub'))}</section><section><h2>${esc(tr('next'))}</h2>${tasks.filter(t=>t.date>today||((t.endDate||t.date)<today&&!['done','cancelled'].includes(t.status))).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,30).map(t=>taskCard(t,true)).join('')||empty(tr('empty'))}</section></div>`}`;}
function clientHTML(){let p=ownerRole?C.customerProject(state):state.clientData,tasks=p.tasks||[],next=tasks.filter(t=>t.status!=='done'),done=tasks.filter(t=>t.status==='done');return `<div class="client-page">${ownerRole?`<div class="row between" style="margin-bottom:14px"><span class="muted">客户视图预览：只展示已发布并允许公开的施工内容。</span><div class="row">${button('发布现场更新','clientUpdate','','primary')}${button('导出客户进度页','clientExport')}</div></div>`:''}<section class="hero"><div class="eyebrow" style="color:#9ed6c1">YUAN DESIGN BUILD</div><h2>${esc(p.name)}</h2><p>${esc(tr('customer'))}</p><div style="margin-top:20px;font-size:34px;font-weight:650">${p.progress||0}% <small style="font-size:12px;font-weight:400">${esc(tr('progress').replace(' %',''))}</small></div><div class="progress" style="background:#447971"><span style="width:${p.progress||0}%;background:#a2d9bc"></span></div><div class="row between"><span class="muted">${esc(tr('finished'))}: ${done.length} / ${tasks.length}</span><span class="muted">${esc(tr('updated'))}: ${p.updatedAt?new Date(p.updatedAt).toLocaleString(lang):'—'}</span></div></section><div class="grid two"><section><h2>${esc(tr('nextDetails'))}</h2><p class="muted">${esc(tr('readOnly'))}</p>${next.length?next.sort((a,b)=>a.date.localeCompare(b.date)).slice(0,12).map(t=>`<div class="task-card"><div class="row between">${statusPill(t)}<span class="muted">${t.date}</span></div><h3>${esc(C.title(t,lang))}</h3>${t.details?`<p class="note-text">${esc(t.details)}</p>`:''}</div>`).join(''):empty(tr('noPublic'))}</section><section><h2>${esc(tr('siteUpdate'))}</h2><div class="timeline" style="margin-top:23px">${p.updates.length?[...p.updates].reverse().map(u=>`<div class="timeline-item"><span class="muted">${esc(u.date)}</span><p class="note-text">${esc(u.text)}</p>${photoHTML(u.photos)}</div>`).join(''):'<p class="muted">—</p>'}</div></section></div></div>`;}
function settingsHTML(){let p=state.project;return `<section><div class="row between"><div><h2>项目资料与数据保护</h2><p class="muted">修改项目参数会提示重新复核图纸和用料，施工任务、采购及库存流水会继续保留。</p></div>${button('新建项目','newProject','','primary')}</div><form id="projectForm"><div class="grid" style="margin-top:18px">${field('项目名称','name',p.name,'text','required maxlength="150"')}${field('建筑面积 m²','area',p.area,'number','min="0" step=".01" required')}${field('地板面积 m²','floor',p.floor,'number','min="0" step=".01" required')}${field('墙面面积 m²','wall',p.wall,'number','min="0" step=".01" required')}${field('估算线路长度 m','route',p.route,'number','min="0" step=".01" required')}${field('计划开始日期','start',p.start,'date','required')}${field('预算 €','budget',p.budget,'number','min="0" step=".01" required')}</div><h3 style="margin-top:20px">工作日设置</h3><div class="row">${['周日','周一','周二','周三','周四','周五','周六'].map((d,i)=>`<label class="check-line"><input type="checkbox" name="workdays" value="${i}" ${p.workdays.includes(i)?'checked':''}>${d}</label>`).join('')}</div>${field('不安排施工的日期（逗号分隔，YYYY-MM-DD）','holidays',p.holidays.join(', '))}<p class="muted">自定义休息日与假期。调整设置不会自动改动已安排的任务日期。</p><button class="primary">保存项目资料</button></form></section><section><h2>导入、备份与恢复</h2><p class="muted">支持原始 YUAN_project.json、v3.2/v3.3 文件，以及完整 v3.4 多项目备份。v3.4 恢复保留任务、审批、到货、库存和操作记录。</p><div class="row" style="margin-top:16px"><label class="file-label">导入项目 / 备份<input id="importBackup" type="file" accept="application/json,.json"></label>${button('导出完整备份 JSON','export','','primary')}${button('自动恢复点','recoveries')}${serverRole==='owner'?button('立即同步','sync'):''}</div><p class="notice ${cloudConflict?'danger':'good'}">${serverRole==='owner'?'已启用云端保存。离线修改先保存在此设备，联网后同步；出现版本冲突时保留双方数据。':'当前为本机文件模式。数据保存在这个浏览器，请定期导出备份；跨设备共同使用需打开在线版。'}</p></section><section><h2>协作账户</h2><p class="muted">在线版按登录邮箱匹配工人或客户；工人只能操作自己的任务，客户只能查看公开进度。还需为这些账户设置网站访问权限。</p>${serverRole==='owner'?button('登记协作账户','newMember'):''}${workspace.members.length?`<div class="scroll"><table><thead><tr><th>邮箱</th><th>角色</th><th>项目</th><th></th></tr></thead><tbody>${workspace.members.map(m=>`<tr><td>${esc(m.email)}</td><td>${m.role==='foreman'?'工长':m.role==='worker'?'工人':'客户'}</td><td>${esc(workspace.projects.find(p=>p.id===m.projectId)?.project.name||'')}</td><td>${button('移除授权','removeMember',m.id)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">未登记协作账户。</p>'}</section><section><h2>最近操作记录</h2>${state.activity.length?[...state.activity].reverse().slice(0,40).map(e=>`<div class="alert-item"><div><span class="muted">${new Date(e.at).toLocaleString('es-ES')} · ${esc(e.actor)}</span><div>${esc(e.text)}</div></div></div>`).join(''):'<p class="muted">尚无操作记录。</p>'}</section>`;}

function modal(title,body,onSubmit,submitLabel=tr('save')){let d=document.getElementById('modal');if(d.open)d.close();d.innerHTML=`<header><h2>${esc(title)}</h2><button type="button" data-close aria-label="${esc(tr('cancel'))}">×</button></header><form><div class="form-error" role="alert"></div>${body}<div class="form-actions"><button type="button" data-close>${esc(tr('cancel'))}</button><button type="submit" class="primary">${esc(submitLabel)}</button></div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.querySelector('form').onsubmit=async e=>{e.preventDefault();let f=e.currentTarget;if(!f.reportValidity())return;let btn=f.querySelector('[type=submit]');if(btn.disabled)return;btn.disabled=true;let error=f.querySelector('.form-error');error.style.display='none';try{await onSubmit(f,new FormData(f));d.close();}catch(ex){error.textContent=ex.message;error.style.display='block';}finally{btn.disabled=false;}};d.showModal();return d;}
function materialLines(lines=[],prices=false){if(!lines.length)lines=[{materialId:C.catalog(state)[0]?.id||'',qty:'',price:''}];return `<div id="materialLines">${lines.map(l=>lineHTML(l,prices)).join('')}</div>${button('＋ '+tr('material'),'addMaterialLine',prices?'prices':'')}`;}
function lineHTML(l={},prices=false){return `<div class="material-line" style="${prices?'grid-template-columns:minmax(120px,1fr) 80px 90px 36px':''}"><select name="materialId" aria-label="${esc(tr('material'))}">${C.catalog(state).map(m=>`<option value="${esc(m.id)}" ${m.id===l.materialId?'selected':''}>${esc(pickName(m))} (${esc(m.unit)})</option>`).join('')}</select><input name="materialQty" type="number" min=".001" step=".001" value="${esc(l.qty??'')}" placeholder="${esc(tr('qty'))}" aria-label="${esc(tr('qty'))}" required>${prices?`<input name="materialPrice" type="number" min="0" step=".001" value="${esc(l.price??'')}" placeholder="单价 €" aria-label="单价 €">`:''}<button type="button" data-remove-line aria-label="${esc(tr('cancel'))}">×</button></div>`;}
function readLines(f,prices=false){let rows=[...f.querySelectorAll('.material-line')];let seen=new Set();return rows.map(row=>{let materialId=row.querySelector('[name=materialId]').value,qty=C.number(row.querySelector('[name=materialQty]').value,tr('qty'),.001);if(seen.has(materialId))throw Error('同一材料请合并数量');seen.add(materialId);let price=row.querySelector('[name=materialPrice]')?.value;return {id:C.uid('line'),materialId,qty,received:0,...(prices?{price:price===''||price==null?null:C.number(price,'单价')}: {})};});}
function editTask(id='',date=boardDate){let old=state.tasks.find(t=>t.id===id);if(old&&['done','review'].includes(old.status))return reviewTask(id);let t=old||{title:'',date,endDate:date,time:'08:00',endTime:'17:00',workerId:'',details:'',clientDetails:'',materials:[],checks:[],dependencies:[],public:true,phaseId:'custom'};
 modal(old?'编辑任务':'新建每日任务',`<div class="grid">${field('任务名称','title',t.title,'text','required maxlength="160"')}${select('施工负责人','workerId',[['','待分配'],...state.project.workers.filter(w=>w.active!==false).map(w=>[w.id,w.name])],t.workerId)}${field('开始日期','date',t.date,'date','required')}${field('结束日期','endDate',t.endDate||t.date,'date','required')}${field('开始时间','time',t.time,'time','required')}${field('结束时间','endTime',t.endTime,'time','required')}${select('工序','phaseId',[['custom','自定义'],...C.phaseDefs.map(p=>[p.id,p.titles[0]])],t.phaseId)}</div>${area('施工要求 / 现场交代','details',t.details)}${area('客户可见的施工说明','clientDetails',t.clientDetails||'')}<label class="check-line"><input type="checkbox" name="public" ${t.public?'checked':''}>发布后可出现在客户进度页</label><h3>所需材料</h3><p class="muted">填写这项任务实际要用的量。模板估算须核实；不填材料也可以保存任务。</p>${materialLines(t.materials)}<h3 style="margin-top:18px">前置任务</h3><select name="dependencies" multiple style="width:100%;min-height:90px">${state.tasks.filter(x=>x.id!==id&&x.status!=='cancelled').map(x=>`<option value="${esc(x.id)}" ${(t.dependencies||[]).includes(x.id)?'selected':''}>${esc(x.date+' · '+x.title)}</option>`).join('')}</select>${area('验收检查项（每行一条）','checks',(t.checks||[]).map(c=>c.text).join('\n'))}${old?`<div style="margin-top:15px">${button('取消此任务','cancelTask',id,'danger-btn')}</div>`:''}`,async(f,d)=>{let materials=readLines(f);await change(()=>{let next={...t,id:old?.id||C.uid('task'),title:d.get('title').trim(),workerId:d.get('workerId'),date:d.get('date'),endDate:d.get('endDate'),time:d.get('time'),endTime:d.get('endTime'),phaseId:d.get('phaseId'),details:d.get('details'),clientDetails:d.get('clientDetails'),public:d.has('public'),materials,checks:String(d.get('checks')).split('\n').filter(x=>x.trim()).map(text=>({text,done:t.checks?.find(c=>c.text===text)?.done||false})),dependencies:d.getAll('dependencies'),status:old?.status||'draft',progress:old?.progress||0,estimated:false,updatedAt:new Date().toISOString()};if(old&&old.title!==next.title){delete next.titles;delete next.dayIndex;delete next.phaseDays;}if(!next.title)throw Error('请填写任务名称');if(old)state.tasks[state.tasks.findIndex(x=>x.id===id)]=next;else state.tasks.push(next);C.log(state,'task',`${old?'更新':'新增'}任务：${next.title}`);},'任务已保存');});}
function newWorker(){modal('添加施工人员',`<div class="grid">${field('姓名','name','','text','required maxlength="80"')}${select('工种','skill',[['general','综合施工'],['electrical','电工'],['plumbing','水工']])}${field('邮箱（用于跨项目识别同一人员）','email','','email')}${select('工作语言','language',C.languages.map((l,i)=>[l,['中文','Español','English','हिन्दी'][i]]),'es')}</div>`,async(f,d)=>change(()=>{let name=d.get('name').trim();if(!name)throw Error('请填写姓名');if(state.project.workers.some(w=>w.name===name&&w.active!==false))throw Error('姓名重复，请使用可区分的姓名');state.project.workers.push({id:C.uid('worker'),name,skill:d.get('skill'),email:d.get('email').trim().toLowerCase(),language:d.get('language'),active:true});C.log(state,'worker','添加员工：'+name);},'员工已添加'));}
function manageWorkers(){let workers=state.project.workers;modal('施工人员管理',workers.map(w=>`<div class="subtle" data-edit-worker="${esc(w.id)}" style="margin-bottom:12px"><div class="grid">${field('姓名','workerName',w.name,'text','required')}${select('工种','workerSkill',[['general','综合施工'],['electrical','电工'],['plumbing','水工']],w.skill)}${field('邮箱','workerEmail',w.email||'','email')}${select('工作语言','workerLanguage',C.languages.map((l,i)=>[l,['中文','Español','English','हिन्दी'][i]]),w.language||'es')}</div><label class="check-line"><input type="checkbox" name="workerActive" ${w.active!==false?'checked':''}>在岗</label></div>`).join(''),async(f)=>change(()=>{let names=new Set();for(let row of f.querySelectorAll('[data-edit-worker]')){let w=state.project.workers.find(w=>w.id===row.dataset.editWorker),name=row.querySelector('[name=workerName]').value.trim();if(!name||names.has(name))throw Error('姓名为空或重复');names.add(name);Object.assign(w,{name,skill:row.querySelector('[name=workerSkill]').value,email:row.querySelector('[name=workerEmail]').value.trim().toLowerCase(),language:row.querySelector('[name=workerLanguage]').value,active:row.querySelector('[name=workerActive]').checked});}C.log(state,'worker','更新员工资料与在岗状态');},'已保存'));}
function materialForm(id=''){let old=C.catalog(state).find(m=>m.id===id)||{name:'',unit:'pcs',pack:1,lead:0,price:null,supplier:''};modal(id?'材料规格':'新增材料',`<div class="grid">${field('材料名称 / 规格','name',old.name,'text','required maxlength="160"')}${field('单位','unit',old.unit,'text','required maxlength="12"')}${field('包装数量','pack',old.pack,'number','required min=".001" step=".001"')}${field('交期（自然日）','lead',old.lead,'number','required min="0" max="730" step="1"')}${field('参考单价 €（可留空）','price',old.price??'','number','min="0" step=".001"')}${field('供应商 / 规格备注','supplier',old.supplier||'')}</div><p class="muted">参考价由你填写，不是商店实时报价；批准采购时可填写实际单价。</p>`,async(f,d)=>change(()=>{let next={...old,id:id||C.uid('mat'),name:d.get('name').trim(),unit:d.get('unit').trim(),pack:C.number(d.get('pack'),'包装数量',.001),lead:C.number(d.get('lead'),'交期'),price:d.get('price')===''?null:C.number(d.get('price'),'单价'),supplier:d.get('supplier'),estimated:false};if(!next.name||!next.unit)throw Error('请填写材料和单位');if(next.name!==old.name)delete next.names;let index=state.materials.findIndex(m=>m.id===id);if(index>=0)state.materials[index]=next;else state.materials.push(next);C.log(state,'material','登记材料规格：'+next.name);},'材料已保存'));}
function countStock(id){let m=C.catalog(state).find(m=>m.id===id),s=C.stock(state,id);modal('现场库存盘点',`<h3>${esc(pickName(m))}</h3><p class="muted">${s.known?'当前账面：'+fmt(s.qty)+' '+m.unit:'尚未盘点。请填写现场真实可用数量。'}</p><div class="grid">${field('实际可用数量 '+m.unit,'qty',s.known?s.qty:'','number','required min="0" step=".001"')}${field('盘点说明','note','','text','required')}</div>`,async(f,d)=>change(()=>{C.move(state,{materialId:id,type:'count',qty:d.get('qty'),note:d.get('note')});C.log(state,'stock','实盘 '+pickName(m)+'：'+d.get('qty')+' '+m.unit);},'盘点已登记'));}
function moveStock(id){let m=C.catalog(state).find(m=>m.id===id);modal('材料领用、退回与损耗',`<h3>${esc(pickName(m))}</h3><div class="grid">${select('操作','type',[['issue','领用'],['return','任务剩料退回'],['waste','仓库损耗']])}${select('关联任务','taskId',[['','请选择'],...state.tasks.filter(t=>t.status!=='cancelled'||C.netIssued(state,t.id,id)>0).map(t=>[t.id,t.title])])}${field('实际数量 '+m.unit,'qty','','number','required min=".001" step=".001"')}${field('经手 / 原因说明','note','','text','required')}</div>`,async(f,d)=>change(()=>{C.move(state,{materialId:id,type:d.get('type'),qty:d.get('qty'),taskId:d.get('taskId'),note:d.get('note')});C.log(state,'stock','材料'+({issue:'领用',return:'退回',waste:'损耗'})[d.get('type')]+'：'+pickName(m)+' '+d.get('qty'));},'库存已更新'));}
function requestForm(taskId='',prefill=[]){let task=state.tasks.find(t=>t.id===taskId);let lines=prefill.length?prefill:task?(task.materials||[]).map(m=>({...m,qty:C.taskMaterials(state,task).find(x=>x.materialId===m.materialId)?.remaining||m.qty})):[];
 modal(tr('requestTitle'),`<div class="grid">${field(tr('needDate'),'needDate',task?.date||C.today(),'date','required')}${field(({zh:'供应商',es:'Proveedor',en:'Supplier',hi:'आपूर्तिकर्ता'})[lang],'supplier','')}</div>${area(tr('reason'),'reason','',true)}<label class="check-line"><input type="checkbox" name="urgent">${esc(tr('urgent'))}</label><h3>${esc(tr('need'))}</h3>${materialLines(lines)}`,async(f,d)=>{let lines=readLines(f);if(!lines.length)throw Error(tr('required'));let reason=d.get('reason').trim();if(!reason)throw Error(tr('required'));const request={id:C.uid('request'),code:'MR-'+C.today().replaceAll('-','')+'-'+C.uid().slice(-5).toUpperCase(),taskId,needDate:d.get('needDate'),supplier:d.get('supplier'),reason,urgent:d.has('urgent'),lines,status:'pending',requestedBy:view==='workers'?workerName(workerFilter):'Qi Yuan',at:new Date().toISOString()};if(!ownerRole)await workerRemote('request',taskId,{request});else await change(()=>{state.requests.push(request);C.log(state,'request','提出材料申请：'+request.code,request.requestedBy);},tr('submitted'));},tr('send'));
}
function approveRequest(id){let r=state.requests.find(x=>x.id===id);if(r?.status!=='pending')throw Error('申请状态已变化');modal('审批材料申请',`<p class="note-text">${esc(r.reason)}</p><p class="muted">${esc(r.code)} · 数量按本次批准为准。采购仍由 Qi Yuan 负责。</p>${materialLines(r.lines,true)}${area('审批备注','note',r.approvalNote||'')}`,async(f,d)=>change(()=>{let lines=readLines(f,true);if(!lines.length)throw Error('请保留至少一条材料');r.lines=lines;r.status='approved';r.approvalNote=d.get('note');r.approvedAt=new Date().toISOString();r.approvedBy='Qi Yuan';C.log(state,'approval','批准采购：'+r.code);},'已批准，等待下单'),'批准采购');}
function orderRequest(id){let r=state.requests.find(x=>x.id===id);if(r?.status!=='approved')throw Error('请先审批');modal('登记实际下单',`<p>${esc(r.code)}</p><div class="grid">${field('供应商','supplier',r.supplier,'text','required')}${field('预计到货日期','eta',r.needDate,'date','required')}${field('订单 / 发票备注','orderRef',r.orderRef||'')}</div><p class="notice warning">这里只登记已下单，不会增加库存。实际收货后逐项登记到货。</p>`,async(f,d)=>change(()=>{r.status='ordered';r.supplier=d.get('supplier').trim();r.eta=d.get('eta');r.orderRef=d.get('orderRef');r.orderedAt=new Date().toISOString();C.log(state,'order','登记下单：'+r.code);},'下单已登记'));}
function receiveRequest(id){let r=state.requests.find(x=>x.id===id);if(!r)return;let op=C.uid('receipt');modal('实际到货入库',`<p>${esc(r.code)} · 填写本次实际收到数量。</p>${r.lines.filter(l=>l.qty>(l.received||0)).map(l=>{let m=C.catalog(state).find(m=>m.id===l.materialId);return field(pickName(m)+' · 尚欠 '+C.round(l.qty-(l.received||0))+' '+m?.unit,l.id,0,'number',`min="0" max="${C.round(l.qty-(l.received||0))}" step=".001" required`);}).join('')}<p class="muted">可以分批收货。重复点击提交不会重复入库。</p>`,async(f,d)=>change(()=>{C.receive(state,id,r.lines.map(l=>({lineId:l.id,qty:d.get(l.id)||0})),op);},'本次到货已入库'));}
async function taskAction(id,action,payload={}){let t=state.tasks.find(x=>x.id===id);if(!t)throw Error('任务不存在');if(!ownerRole)return workerRemote(action,id,payload);return change(()=>{applyTaskAction(t,action,payload);C.log(state,'task',tr(action==='ack'?'acceptedMsg':action==='start'?'started':'submitted')+'：'+t.title,workerName(t.workerId));},tr('submitted'));}
function applyTaskAction(t,action,payload){if(action==='ack'){if(t.status!=='assigned')throw Error('任务状态已变化');t.status='accepted';t.ackAt=new Date().toISOString();}else if(action==='start'){if(!['accepted','blocked'].includes(t.status))throw Error('请先接单');if(C.blockers(state,t).length)throw Error(tr('dependencies'));t.status='in_progress';t.startedAt??=new Date().toISOString();t.blockReason='';}else if(action==='block'){if(!['accepted','in_progress'].includes(t.status))throw Error('任务状态已变化');t.status='blocked';t.blockReason=payload.reason;t.blockedAt=new Date().toISOString();}else if(action==='report'){if(!['in_progress','blocked'].includes(t.status))throw Error('请先开始任务');let p=C.number(payload.progress,'进度',0,100);if(p===100&&payload.checks.some(c=>!c.done))throw Error(({zh:'请完成全部验收检查项',es:'Complete las comprobaciones',en:'Complete all checklist items',hi:'सभी जाँच पूरी करें'})[lang]);t.progress=p;t.status=p===100?'review':'in_progress';t.checks=payload.checks;t.blockReason='';state.reports.push({id:C.uid('report'),taskId:t.id,workerId:t.workerId,at:new Date().toISOString(),...payload});}t.updatedAt=new Date().toISOString();state.publishedAt=new Date().toISOString();}
const CHECK_TRANSLATIONS={
 '作业范围已确认':['Zona de trabajo confirmada','Work area confirmed','काम का क्षेत्र तय है'],'清运完成并清洁现场':['Retirada y limpieza terminadas','Clearance and cleaning complete','मलबा हटाया और सफाई पूरी'],
 '对照审核图纸定位':['Replanteo según plano validado','Set out against verified drawing','सत्यापित ड्रॉइंग के अनुसार मार्किंग'],'高度及参照尺寸已核对':['Alturas y cotas comprobadas','Heights and reference dimensions checked','ऊँचाई और माप जाँचे गए'],
 '回路及线径按核定图纸':['Circuitos y secciones según plano validado','Circuits and cable sizes match verified design','सर्किट और तार डिज़ाइन के अनुसार'],'封闭前拍照并待验收':['Fotos antes del cierre y revisión pendiente','Photos taken before closing; approval required','बंद करने से पहले फ़ोटो और जाँच'],
 '按核定点位施工':['Instalación en puntos validados','Installed at verified positions','सत्यापित स्थानों पर काम'],'测试结果记录并待验收':['Pruebas registradas; revisión pendiente','Test results recorded; approval required','परीक्षण दर्ज, जाँच बाकी'],
 '现场测试与照片齐全':['Pruebas y fotos completas','Site tests and photos complete','परीक्षण और फ़ोटो पूरे'],'批准后才封闭':['Cerrar solo tras aprobación','Close only after approval','अनुमति के बाद ही बंद करें'],
 '基层与材料已核对':['Soporte y materiales comprobados','Substrate and materials checked','आधार और सामग्री जाँचे गए'],'完成面质量检查':['Calidad del acabado comprobada','Finished surface quality checked','तैयार सतह की गुणवत्ता जाँची'],
 '按点位安装并测试':['Instalación y pruebas en puntos previstos','Installed and tested at specified points','निर्धारित स्थान पर लगाकर परीक्षण'],'保护成品并清洁':['Acabados protegidos y zona limpia','Finished work protected and area cleaned','तैयार काम सुरक्षित और साफ़'],
 '缺陷清单复查':['Lista de defectos revisada','Defect list rechecked','खामियों की सूची दोबारा जाँची'],'交付资料齐全':['Documentación de entrega completa','Handover documents complete','हैंडओवर दस्तावेज़ पूरे']};
const checkText=s=>lang==='zh'?s:CHECK_TRANSLATIONS[s]?.[C.languages.indexOf(lang)-1]||s;
async function readPhotos(input){let files=[...(input?.files||[])];if(files.length>4)throw Error('最多 4 张照片 / Maximum 4 photos');let out=[];for(let f of files){if(!/^image\/(jpeg|png|webp)$/.test(f.type)||f.size>20e6)throw Error('请上传 JPG / PNG / WebP，单张小于 20MB');let bitmap=await createImageBitmap(f),scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();out.push({id:C.uid('photo'),data:canvas.toDataURL('image/jpeg',.76)});}return out;}
function reportTask(id){let t=state.tasks.find(x=>x.id===id);modal(tr('reportTitle'),`<h3>${esc(C.title(t,lang))}</h3>${field(tr('progress'),'progress',t.progress||0,'number','required min="0" max="100" step="1"')}${area(tr('comment'),'text','',true)}<h3>${esc(tr('checks'))}</h3>${(t.checks||[]).map((c,i)=>`<label class="check-line"><input type="checkbox" name="check" value="${i}" ${c.done?'checked':''}>${esc(checkText(c.text))}</label>`).join('')}<label class="field">${esc(tr('photos'))}<input type="file" name="photos" multiple accept="image/jpeg,image/png,image/webp"></label>`,async(f,d)=>{let photos=await readPhotos(f.elements.photos),checked=new Set(d.getAll('check'));await taskAction(id,'report',{progress:+d.get('progress'),text:d.get('text').trim(),checks:(t.checks||[]).map((c,i)=>({...c,done:checked.has(String(i))})),photos});},tr('send'));}
function blockTask(id){modal(tr('blockTitle'),area(tr('reason'),'reason','',true),async(f,d)=>{let reason=d.get('reason').trim();if(!reason)throw Error(tr('required'));await taskAction(id,'block',{reason});},tr('send'));}
function reviewTask(id){let t=state.tasks.find(x=>x.id===id),reports=state.reports.filter(r=>r.taskId===id);modal('任务报告与验收',`<h3>${esc(t.title)}</h3><p>${statusPill(t)} · ${esc(workerName(t.workerId))}</p>${reports.length?reports.map(r=>`<div class="subtle" style="margin:12px 0"><span class="muted">${new Date(r.at).toLocaleString('es-ES')} · ${r.progress}%</span><p class="note-text">${esc(r.text)}</p>${photoHTML(r.photos)}</div>`).join(''):'<p class="muted">暂无工人报告。</p>'}${ownerRole&&t.status==='review'?`${select('验收决定','decision',[['done','验收通过'],['rework','退回整改']])}${area('验收 / 整改说明','reviewNote','',true)}`:'<p class="muted">任务已验收，记录保留。</p>'}`,async(f,d)=>{if(!ownerRole||t.status!=='review')return;await change(()=>{if(d.get('decision')==='done'){t.status='done';t.progress=100;t.verifiedAt=new Date().toISOString();t.reviewNote=d.get('reviewNote');}else{t.status='in_progress';t.progress=Math.min(99,t.progress);t.reviewNote=d.get('reviewNote');t.details+='\n整改：'+d.get('reviewNote');}state.publishedAt=new Date().toISOString();C.log(state,'review','任务验收：'+t.title+' · '+d.get('reviewNote'));},'验收结果已保存');},ownerRole&&t.status==='review'?'保存验收结果':'关闭');}

async function workerRemote(action,taskId,payload){const operationId=C.uid('workerop');await api('/api/actions',{method:'POST',body:JSON.stringify({action,taskId,projectId:state.id,payload,operationId})});await fetchCloud(false);toast(tr('submitted'));}
function publishTasks(ids){modal('发布施工任务',`<p>本次发布 ${ids.length} 项任务。工人登录自己的账户后可以查看并确认接单；系统不会自动发送聊天消息。</p><p class="muted">发布前请核实工期、负责人、施工要求及材料量。未盘点库存不妨碍排班。</p>`,async()=>change(()=>{for(let id of ids){let t=state.tasks.find(x=>x.id===id);if(!t||t.status!=='draft')throw Error('任务状态已变化');if(!state.project.workers.some(w=>w.id===t.workerId&&w.active!==false))throw Error('有任务尚未指定在岗负责人');t.status='assigned';t.publishedAt=new Date().toISOString();}state.publishedAt=new Date().toISOString();C.log(state,'publish','发布 '+ids.length+' 项施工任务');},'任务已发布'),'发布任务');}
function clientUpdate(){modal('发布客户现场更新',`${field('日期','date',C.today(),'date','required')}${area('客户可见内容','text','',true)}<label class="field">现场照片<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="muted">内容及所选照片会出现在客户进度页，请核对后发布。</p>`,async(f,d)=>{let photos=await readPhotos(f.elements.photos);await change(()=>{state.clientUpdates.push({id:C.uid('update'),date:d.get('date'),text:d.get('text').trim(),photos,published:true});state.publishedAt=new Date().toISOString();C.log(state,'client','发布客户进度更新');},'客户进度已更新');},'发布更新');}
async function embedAssets(value){let out=C.clone(value);async function walk(v){if(!v||typeof v!=='object')return;for(let k of Object.keys(v)){if(typeof v[k]==='string'&&/^\/api\/assets\/[a-zA-Z0-9_-]+$/.test(v[k])){let r=await fetch(v[k],{credentials:'same-origin'});if(!r.ok)throw Error('照片读取失败，备份未完成');let b=await r.blob();v[k]=await new Promise((res,rej)=>{let f=new FileReader();f.onload=()=>res(f.result);f.onerror=rej;f.readAsDataURL(b);});}else if(typeof v[k]==='object')await walk(v[k]);}}await walk(out);return out;}
async function exportBackup(){await saving.catch(()=>{});let out=await embedAssets(workspace);delete out._sync;out.exportedAt=new Date().toISOString();dl('YUAN_BUILD_OS_v3.4_'+C.today()+'.json',JSON.stringify(out,null,2),'application/json');toast('完整备份已下载');}
async function clientExport(){let p=await embedAssets(C.customerProject(state));const html=`<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(p.name)} · YUAN</title><style>body{font:15px/1.7 system-ui,sans-serif;color:#173c3b;max-width:850px;margin:35px auto;padding:20px;background:#f5f8f6}header,section{background:white;border:1px solid #dce8e2;border-radius:13px;padding:24px;margin-bottom:20px}h1{font-size:26px}h2{font-size:18px}small{color:#6b8178}article{padding:13px 0;border-top:1px solid #e0e9e4}p{white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%;max-height:400px;border-radius:9px}</style></head><body><header><small>YUAN DESIGN BUILD</small><h1>${esc(p.name)}</h1><h2>施工进度 ${p.progress}%</h2><small>此为进度快照，生成于 ${esc(new Date().toLocaleString('es-ES'))}；后续更新请查看在线客户进度页。</small></header><section><h2>施工安排</h2>${p.tasks.map(t=>`<article><small>${esc(t.date)} · ${esc(tr(t.status))}</small><h3>${esc(C.title(t,lang))}</h3><p>${esc(t.details)}</p></article>`).join('')||'<p>暂无已公开安排</p>'}</section><section><h2>现场进展</h2>${p.updates.map(u=>`<article><small>${esc(u.date)}</small><p>${esc(u.text)}</p>${(u.photos||[]).map(ph=>`<img src="${safePhoto(ph.data||ph)}" alt="现场进展">`).join('')}</article>`).join('')}</section></body></html>`;dl('YUAN_customer_progress_'+C.today()+'.html',html,'text/html;charset=utf-8');}
function csvExport(){const cell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};let cat=C.catalog(state),rows=[['申请编号','申请人','状态','材料','规格单位','批准数量','已收数量','单价EUR','需要日期','预计到货','供应商','原因'],...state.requests.flatMap(r=>r.lines.map(l=>[r.code,r.requestedBy,r.status,pickName(cat.find(x=>x.id===l.materialId)),cat.find(x=>x.id===l.materialId)?.unit,l.qty,l.received||0,l.price??'',r.needDate,r.eta||'',r.supplier,r.reason]))];dl('YUAN_purchase_v3.4_'+C.today()+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function loadImport(file){if(!file)return;if(file.size>45e6)throw Error('备份过大，请使用 45MB 以内的文件');const raw=JSON.parse(await file.text()),imported=C.workspace(raw),complete=raw.schema==='yuan-build-os';modal('导入已核对的项目文件',`<p>已读取 ${imported.projects.length} 个项目，${imported.projects.reduce((n,p)=>n+p.tasks.length,0)} 项任务。</p>${select('导入方式','mode',[['append','添加为新项目，保留现有资料'],...(complete?[['replace','恢复整份备份，替换当前工作区']]:[])])}<p class="notice warning">完整备份恢复会保留原有审批与库存流水；原始项目文件的 verified、manual 测试数量不会自动成为真实工程确认。</p>`,async(f,d)=>change(()=>{if(d.get('mode')==='replace'){workspace={...imported,revision:localRevision};}else{for(let p of imported.projects){p.id=C.uid('project');workspace.projects.push(p);}workspace.activeProjectId=imported.projects[0].id;}selectActive();C.log(state,'import','导入项目：'+file.name);view='dashboard';},'项目已导入'));}
let recoveryList=[];
async function recoveries(){recoveryList=(await S.recoveries()).sort((a,b)=>b.revision-a.revision);modal('自动恢复点',recoveryList.length?`${select('选择恢复点','rev',recoveryList.map(w=>[String(w.revision),(w.savedAt?new Date(w.savedAt).toLocaleString('es-ES'):'')+' · '+w.projects.length+' 个项目 · v'+w.revision]))}<p class="notice warning">恢复前可先导出当前备份。恢复会保留当前版本为新的恢复点。</p>`:'<p>还没有自动恢复点。</p>',async(f,d)=>{let old=recoveryList.find(w=>String(w.revision)===d.get('rev'));if(!old)return;await change(()=>{workspace=C.workspace(old);workspace.revision=localRevision;selectActive();},'恢复完成');},'恢复所选版本');}
function newProject(){modal('新建施工项目',`${field('项目名称','name','','text','required maxlength="150"')}${field('计划开始日期','start',C.today(),'date','required')}`,async(f,d)=>change(()=>{let p=C.project({name:d.get('name').trim(),start:d.get('start')});workspace.projects.push(p);workspace.activeProjectId=p.id;selectActive();view='settings';},'项目已创建'));}
function newMember(){modal('登记协作账户',`<div class="grid">${field('登录邮箱','email','','email','required')}${select('角色','role',[['foreman','工长（排班、申料、库存）'],['worker','工人'],['customer','客户']])}${select('关联工人（客户可不选）','workerId',[['','请选择'],...state.project.workers.map(w=>[w.id,w.name])])}</div><p class="notice warning">此处登记应用内权限。网站当前保持私人访问，账户还需要网站访问授权；不会自动发送邀请。</p>`,async(f,d)=>change(()=>{let email=d.get('email').trim().toLowerCase(),role=d.get('role');if(role==='worker'&&!d.get('workerId'))throw Error('请选择关联工人');if(workspace.members.some(m=>m.email===email&&m.projectId===state.id))throw Error('这个邮箱已有本项目授权');workspace.members.push({id:C.uid('member'),email,role,workerId:role==='worker'?d.get('workerId'):'',projectId:state.id});C.log(state,'access','登记协作账户：'+email);},'账户角色已登记'));}
async function reloadLocal(){if(unsaved&&!confirm('当前有未保存修改。确认先导出备份或放弃这些修改，载入已保存记录？'))return;let w=await S.read();if(!w)return;workspace=C.workspace(w);localRevision=w.revision;cloudRevision=w._sync?.serverRevision||cloudRevision;unsaved=false;selectActive();document.getElementById('banner').innerHTML='';screen();setSave('已载入最新保存记录');}
async function fetchCloud(force=false){let d=await api('/api/workspace');remoteIdentity=d.identity;serverRole=d.role;ownerRole=d.role==='owner';cloudOnline=true;
 if(!ownerRole){cloudRevision=d.revision;const selectedProject=state?.id;workspace=d.workspace;if(workspace.projects.some(p=>p.id===selectedProject))workspace.activeProjectId=selectedProject;selectActive();if(serverRole==='foreman'){if(!['dashboard','plan','materials','workers'].includes(view))view='plan';}else view=serverRole==='customer'?'client':'workers';workerFilter=d.workerId||state.project.workers[0]?.id||'';document.getElementById('backupButton').hidden=true;screen();setSave('在线 · '+tr('updated')+' '+new Date().toLocaleTimeString('es-ES'));return;}
 if(d.workspace&&(force||(!unsaved&&!workspace._sync?.pending&&d.revision!==cloudRevision))){let next=C.workspace(d.workspace);next.revision=localRevision;next._sync={serverRevision:d.revision,pending:false};localRevision=await S.save(next,localRevision);workspace=next;workspace.revision=localRevision;selectActive();cloudRevision=d.revision;cloudConflict=false;document.getElementById('banner').innerHTML='';screen();setSave('已载入云端最新数据');}
 else if(d.workspace&&workspace._sync?.pending&&d.revision!==cloudRevision){cloudConflict=true;document.getElementById('banner').innerHTML=`<div class="save-warning">此设备有待同步修改，云端也有更新。请先导出备份，再载入云端并核对。 ${button('导出备份','export')} ${button('载入云端最新版本','reloadCloud')}</div>`;}
 else if(!d.workspace){if(d.initialProject&&state.project._placeholder){workspace=C.workspace(d.initialProject);workspace.revision=localRevision;selectActive();}cloudRevision=0;workspace._sync={serverRevision:0,pending:true,mutationId:C.uid('mutation')};await save();}
 return d;
}
const actions={
 go:id=>{view=id;screen();},newTask:()=>editTask(),newTaskDate:d=>editTask('',d),editTask,
 generate:()=>modal('生成施工计划草稿',`<p>将按已选工作日与工种生成 ${C.phaseDefs.reduce((n,p)=>n+p.days,0)} 个每日任务，供工长逐项核定。</p><p class="notice warning">工期、材料与日用量是可编辑估算；不会自动发布，也不会因为没有库存记录而阻止生成。</p>`,async()=>change(()=>{C.generatePlan(state);view='plan';boardDate=state.tasks[0]?.date||C.today();},'施工计划草稿已生成'),'生成草稿'),
 planMode:id=>{planMode=id;screen();},todayBoard:()=>{boardDate=C.today();screen();},
 publishTask:id=>publishTasks([id]),publishWeek:()=>{let ids=state.tasks.filter(t=>t.status==='draft'&&t.date>=boardDate&&t.date<=C.day(boardDate,6)).map(t=>t.id);if(!ids.length)throw Error('本周没有待发布草稿');publishTasks(ids);},
 newWorker,manageWorkers,newProject,newMaterial:()=>materialForm(),editMaterial:materialForm,countStock,moveStock,
 newRequest:()=>requestForm(),taskRequest:id=>requestForm(id),approveRequest,orderRequest,receiveRequest,
 rejectRequest:id=>modal('拒绝材料申请',area('拒绝原因','reason','',true),async(f,d)=>change(()=>{let r=state.requests.find(x=>x.id===id);if(r.status!=='pending')throw Error('申请状态已改变');r.status='rejected';r.rejectionReason=d.get('reason');C.log(state,'approval','拒绝 '+r.code+'：'+r.rejectionReason);},'已登记')),
 cancelRequest:id=>modal('取消已批准申请',area('取消原因','reason','',true),async(f,d)=>change(()=>{let r=state.requests.find(x=>x.id===id);if(r.status!=='approved')throw Error('已下单申请请先处理退货与实际到货记录');r.status='cancelled';r.cancelReason=d.get('reason');C.log(state,'approval','取消 '+r.code+'：'+r.cancelReason);},'申请已取消')),
 cancelTask:id=>modal('取消任务',area('取消原因','reason','',true),async(f,d)=>change(()=>{let t=state.tasks.find(x=>x.id===id);if(state.tasks.some(x=>x.dependencies.includes(id)&&!['done','cancelled'].includes(x.status)))throw Error('请先修改后续任务的前置依赖');t.status='cancelled';t.cancelReason=d.get('reason');C.log(state,'task','取消任务：'+t.title);},'任务已取消')),
 materialView:id=>{materialView=id;screen();},forecastRequest:id=>{let rows=C.forecast(state,+id),lines=rows.filter(m=>m.suggested>0).map(m=>({materialId:m.id,qty:m.suggested}));if(!lines.length)throw Error(rows.some(m=>!m.known)?'先盘点待核实材料，再按缺口生成申请；也可手动新增申请。':'当前没有需要重复申请的数量缺口');requestForm('',lines);},
 ackTask:id=>taskAction(id,'ack'),startTask:id=>taskAction(id,'start'),reportTask,blockTask,reviewTask,clientUpdate,clientExport,
 csv:csvExport,export:exportBackup,recoveries,sync:syncNow,reloadLocal,reloadCloud:async()=>{if(!confirm('请先导出此设备备份。确认载入云端最新版本？'))return;await saving.catch(()=>{});await fetchCloud(true);},
 addMaterialLine:id=>{document.getElementById('materialLines')?.insertAdjacentHTML('beforeend',lineHTML({},id==='prices'));},newMember,
 removeMember:id=>modal('移除应用内授权','<p>移除此账户在应用内的项目访问。网站层面的访问名单保持原状。</p>',async()=>change(()=>{workspace.members=workspace.members.filter(m=>m.id!==id);C.log(state,'access','移除协作账户授权');},'应用内授权已移除'),'移除')
};
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){if(!ownerRole&&serverRole!=='foreman'&&nav.dataset.view!==(serverRole==='customer'?'client':'workers'))return;view=nav.dataset.view;screen();return;}if(e.target.closest('[data-remove-line]')){e.target.closest('.material-line').remove();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;if(!ownerRole&&serverRole!=='foreman'&&!['ackTask','startTask','reportTask','blockTask','taskRequest','addMaterialLine'].includes(action))return;if(serverRole==='foreman'&&!['go','newTask','newTaskDate','editTask','generate','planMode','todayBoard','publishTask','publishWeek','cancelTask','materialView','forecastRequest','newRequest','taskRequest','countStock','moveStock','addMaterialLine'].includes(action))return;try{b.disabled=true;await actions[action]?.(b.dataset.id);}catch(ex){toast(ex.message);}finally{if(b.isConnected)b.disabled=false;}});
function wireNew(){let b=document.getElementById('boardDate');if(b)b.onchange=()=>{if(C.date(b.value)){boardDate=b.value;screen();}};let w=document.getElementById('workerFilter');if(w)w.onchange=()=>{workerFilter=w.value;screen();};let t=document.getElementById('taskFilter');if(t)t.onchange=()=>{taskFilter=t.value;screen();};let f=document.getElementById('projectForm');if(f)f.onsubmit=async e=>{e.preventDefault();let d=new FormData(f);try{await change(()=>{for(let k of ['name','area','floor','wall','route','start','budget'])state.project[k]=['name','start'].includes(k)?d.get(k):C.number(d.get(k),k);state.project.workdays=d.getAll('workdays').map(Number);state.project.holidays=String(d.get('holidays')).split(',').map(s=>s.trim()).filter(Boolean);if(state.project.holidays.some(d=>!C.date(d)))throw Error('假期日期格式有误');invalidate();C.log(state,'project','更新项目资料；现有任务与流水已保留');},'项目资料已保存');}catch(ex){toast(ex.message);}};let imp=document.getElementById('importBackup');if(imp)imp.onchange=()=>loadImport(imp.files[0]).catch(e=>toast('导入失败：'+e.message));}
function wire(){
 document.querySelectorAll('[data-pin]').forEach(e=>e.onchange=()=>{if(!e.checkValidity())return;let k=e.dataset.pin;state.project.points[selected][k]=['height','left','right'].includes(k)?(e.value===''?null:+e.value):e.value;invalidate();save().then(screen).catch(()=>{});});
 const img=document.getElementById('drawingFile');if(img)img.onchange=async()=>{try{let files=await readPhotos(img),image=files[0]?.data;if(!image)return;await change(()=>{state.project.image=image;invalidate();},'图纸已保存');resetView();}catch(e){toast(e.message);}};
 const drawing=document.getElementById('drawingImg');if(drawing)drawing.onload=()=>{if(document.getElementById('drawingImg')===drawing){let fit=mapNaturalSize.src!==state.project.image;mapNaturalSize={src:state.project.image,width:drawing.naturalWidth,height:drawing.naturalHeight};if(fit)resetView();else setupMap();}};
 const cad=document.getElementById('cadFile');if(cad)cad.onchange=()=>loadCAD(cad.files[0]);
 const des=document.getElementById('designerImport');if(des)des.onchange=async()=>{try{let raw=JSON.parse(await des.files[0].text());if(raw.schema!=='yuan-plan-1'||!Array.isArray(raw.points))throw Error('需要 yuan-plan-1 标准格式');let points=raw.points.map(C.point);if(new Set(points.map(p=>p.id)).size!==points.length)throw Error('点位编号重复');if(!confirm('读取 '+points.length+' 个点位，确认替换当前标注？现有任务和流水会保留。'))return;await change(()=>{state.project.points=points;invalidate();selected=null;view='drawing';C.log(state,'drawing','导入设计师点位 '+points.length+' 项');},'点位已导入');}catch(e){toast('导入失败：'+e.message);}};
}
function approveDrawing(){if(!state.project.points.length){toast('请先添加或导入点位');return;}let missing=state.project.points.filter(x=>x.height==null||x.height===''||(!x.leftRef&&!x.rightRef&&!x.note));if(missing.length&&!confirm(missing.length+' 个点位缺少高度或参照说明，仍标记为已审核？'))return;if(!confirm('确认已对照原图核对点位、数量、高度及参照尺寸？'))return;change(()=>{state.approved=true;state.approvedAt=new Date().toISOString();C.log(state,'drawing','确认图纸审核；施工计划与采购流水保留');},'图纸审核已保存').catch(e=>toast(e.message));}
async function loadCAD(file){if(!file)return;if(file.size>20e6){toast('请使用 20MB 以内的 PDF / ASCII DXF');return;}return legacyLoadCAD(file);}
function importCADCandidates(){let chosen=cadCandidates.filter(x=>x.selected);if(!chosen.length){toast('请先选择候选点位');return;}if(!confirm('导入 '+chosen.length+' 个候选点位并替换现有标注？仍需人工核对，施工计划与流水保留。'))return;let seen=new Set();const points=chosen.map((p,i)=>{let base=String(p.id||'CAD-'+(i+1)).slice(0,60),id=base,n=1;while(seen.has(id))id=base+'-'+(++n);seen.add(id);return C.point({...p,id},i);});change(()=>{state.project.points=points;invalidate();state.source='CAD/PDF unverified';selected=null;view='drawing';C.log(state,'drawing','导入 CAD/PDF 候选点位 '+points.length+' 项');},'候选点位已导入，请复核').catch(e=>toast(e.message));}
document.getElementById('lang').onchange=e=>{lang=e.target.value;try{localStorage.setItem('yuan-lang',lang);}catch{}screen();};
document.getElementById('projectSelect').onchange=e=>{workspace.activeProjectId=e.target.value;selectActive();workerFilter='';selected=null;zoom=1;panX=0;panY=0;screen();if(ownerRole)save().catch(()=>{});};
document.getElementById('backupButton').onclick=()=>exportBackup().catch(e=>toast(e.message));
window.addEventListener('beforeunload',e=>{if(unsaved){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>syncNow());
async function init(){
 try{lang=localStorage.getItem('yuan-lang')||'zh';if(!C.languages.includes(lang))lang='zh';}catch{}
 let saved=null;try{saved=await S.read();dbReady=true;}catch(e){document.getElementById('banner').innerHTML=`<div class="save-warning">浏览器存储不可用：${esc(e.message)}。请勿关闭此页面，并使用导出备份保存修改。</div>`;}
 if(saved){try{workspace=C.workspace(saved);localRevision=saved.revision||0;}catch(e){document.getElementById('banner').innerHTML=`<div class="save-warning">本机数据格式异常，原记录已保留。${esc(e.message)}</div>`;}}
 if(!workspace){let legacy=null;try{legacy=JSON.parse(localStorage.getItem('yuan32'));}catch{}workspace=C.workspace(legacy||JSON.parse(document.getElementById('seed').textContent));workspace._sync={pending:false,serverRevision:0};if(dbReady){localRevision=await S.save(workspace,0);workspace.revision=localRevision;}}
 selectActive();cloudRevision=workspace._sync?.serverRevision||0;
 if(location.protocol!=='file:'){try{await fetchCloud(false);}catch(e){if(e.status===403||e.status===401){document.getElementById('root').innerHTML=empty('当前账户没有项目权限','请联系负责人登记与你登录邮箱一致的工人或客户角色。');document.getElementById('backupButton').hidden=true;document.getElementById('projectSelect').hidden=true;setSave('未授权',true);return;}setSave('离线 / 本机模式 · 数据仍保存在此设备');}}
 screen();if(serverRole==='owner'&&workspace._sync?.pending&&!cloudConflict)syncNow();else if(serverRole==='local')setSave('本机模式 · 请定期导出备份');
 setInterval(async()=>{if(document.hidden||document.getElementById('modal').open||unsaved)return;try{if(serverRole==='owner'&&workspace._sync?.pending){await syncNow();}else if(serverRole!=='local')await fetchCloud(false);}catch{cloudOnline=false;}},30000);
}
init().catch(e=>{setSave('加载失败：'+e.message,true);document.getElementById('root').innerHTML=empty('未能完成加载',e.message);});
